CREATE TABLE "acidentado" (
	"id" integer GENERATED BY DEFAULT AS IDENTITY (sequence name "acidentado_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"ocorrencia_id" integer NOT NULL,
	"ordem" integer NOT NULL,
	"vinculo" varchar(14) NOT NULL,
	"servidor_id" integer,
	"participante_id" integer,
	"nome_externo" varchar(160),
	"identificacao_externa" varchar(40),
	"empresa_contratada" varchar(160),
	"fiscal_contrato_servidor_id" integer,
	"condicao" varchar(24) NOT NULL,
	"houve_lesao" varchar(8),
	"cargo_id" integer,
	"funcao" varchar(120),
	"unidade_uorg_id" integer,
	"campus_id" integer,
	"siape" varchar(7),
	"contato_investigacao" varchar(160),
	"menor_de_idade" boolean DEFAULT false NOT NULL,
	"responsavel_legal_solicitado_em" timestamp with time zone,
	"criado_em" timestamp with time zone NOT NULL,
	CONSTRAINT "pk_acidentado" PRIMARY KEY("id"),
	CONSTRAINT "uq_acidentado_ordem" UNIQUE("ocorrencia_id","ordem"),
	CONSTRAINT "ck_acidentado_vinculo" CHECK (vinculo IN ('SERVIDOR','TERCEIRIZADO','ESTUDANTE','BOLSISTA','RESIDENTE','VISITANTE','OUTRO')),
	CONSTRAINT "ck_acidentado_condicao" CHECK (condicao IN ('ACIDENTADO','ENVOLVIDO_SEM_LESAO','CONDUTOR','PASSAGEIRO','PEDESTRE','CICLISTA','MOTOCICLISTA','TESTEMUNHA_ENVOLVIDA','OUTRO')),
	CONSTRAINT "ck_acidentado_lesao" CHECK (houve_lesao IN ('SIM','NAO','NAO_SABE')),
	CONSTRAINT "ck_acidentado_siape" CHECK (siape ~ '^(?:\d{7})$'),
	CONSTRAINT "ck_acidentado_identificacao" CHECK ((servidor_id IS NOT NULL)::int + (participante_id IS NOT NULL)::int + (nome_externo IS NOT NULL)::int = 1),
	CONSTRAINT "ck_acidentado_sem_cpf" CHECK (identificacao_externa !~ '^(?:[0-9]{3}\.?[0-9]{3}\.?[0-9]{3}-?[0-9]{2})$'),
	CONSTRAINT "ck_acidentado_ordem" CHECK (ordem >= 1)
);
